namespace EarlyInterventionCare.Api.Services.Authentication;

public sealed record ParentOtpChallenge(string ChallengeId, DateTimeOffset ExpiresAtUtc, int ResendAfterSeconds);
public sealed record VerifiedParentPhone(string Phone);

// Implement with a real SMS verification provider. Its challenge binds the original phone,
// expires, limits attempts/resends, and is consumed exactly once. Never return or log codes.
// No challenge/code generated by the browser is accepted as evidence.
public interface IParentSmsVerification
{
    Task<ParentOtpChallenge> RequestAsync(string normalizedPhone, CancellationToken ct);
    Task<VerifiedParentPhone?> VerifyAsync(string challengeId, string code, CancellationToken ct);
}

public sealed class ParentSmsUnavailable : IParentSmsVerification
{
    private static Exception Unavailable() => new EarlyInterventionCare.Api.Services.Cases.CaseAccessException(
        "SMS_SERVICE_UNAVAILABLE", 503, "登入服務暫時無法使用，請稍後重試。");

    public Task<ParentOtpChallenge> RequestAsync(string normalizedPhone, CancellationToken ct)
        => Task.FromException<ParentOtpChallenge>(Unavailable());
    public Task<VerifiedParentPhone?> VerifyAsync(string challengeId, string code, CancellationToken ct)
        => Task.FromException<VerifiedParentPhone?>(Unavailable());
}
